using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using UnityEngine;using UnityEngine.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;using UnityEditor;using UnityEditor.SceneManagement;
namespace CodexOutTransfer {
 public static class MergeOutForest {
 const string W="C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/work/",O="C:/Users/lenovo/Documents/Codex/2026-10-16/new-chat/outputs/",Out="Assets/ArtStyleTest/Scenes/out.unity",Forest="Assets/ArtStyleTest/Scenes/Forest_Ruins_Detailed_Study.unity";
 static Scene Main(){var s=SceneManager.GetSceneByPath(Out);if(!s.IsValid()||!s.isLoaded||EditorApplication.isPlaying)throw new Exception("Open out in Edit mode");return s;}
 static Camera View(Scene s){return s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Camera>(true)).First(c=>c.transform.parent&&c.transform.parent.name=="xiangjipingtai"&&c.name=="Camera");}
 static void Capture(Camera c,string name){typeof(OutSceneTransfer).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{c,O+name});}
 [MenuItem("Tools/Out Scene Transfer/Back Up And Inspect Both Scenes")]
 public static void Inspect(){var b=new StringBuilder();try{var main=Main();var forest=SceneManager.GetSceneByPath(Forest);if(!forest.IsValid()||!forest.isLoaded)throw new Exception("Both scenes must be loaded");string dir="Assets/ArtStyleTest/Scenes_BACKUP/Before_OutForestMerge_"+DateTime.Now.ToString("yyyyMMdd_HHmmss");Directory.CreateDirectory(dir);AssetDatabase.Refresh();if(!EditorSceneManager.SaveScene(main,dir+"/out_before_merge.unity",true)||!EditorSceneManager.SaveScene(forest,dir+"/forest_before_merge.unity",true))throw new Exception("Backup failed");b.AppendLine("backup="+dir);var c=View(main);b.AppendLine("outCamera="+c.transform.position.ToString("R")+" rotation="+c.transform.rotation.ToString("R")+" fov="+c.fieldOfView);foreach(var s in new[]{main,forest}){b.AppendLine("SCENE "+s.path+" roots="+s.rootCount+" renderers="+s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Count());foreach(var root in s.GetRootGameObjects()){var rs=root.GetComponentsInChildren<Renderer>(true);var bounds=rs.Length>0?rs[0].bounds:new Bounds(root.transform.position,Vector3.zero);foreach(var r in rs)bounds.Encapsulate(r.bounds);var p=c.WorldToViewportPoint(bounds.center);b.AppendLine("root="+root.name+" active="+root.activeSelf+" position="+root.transform.position.ToString("R")+" meshes="+rs.Length+" bounds="+bounds+" screen="+p.ToString("F2"));}}
 Capture(c,"Out_merge_tone_before.png");b.AppendLine("backedUp=True");}catch(Exception e){b.AppendLine(e.ToString());}File.WriteAllText(W+"out_forest_merge_inspection.txt",b.ToString());}
 [MenuItem("Tools/Out Scene Transfer/Merge Scenes Keep P1 Camera And Match P2 Tone")]
 public static void Merge(){var b=new StringBuilder();try{if(!File.ReadAllText(W+"out_forest_merge_inspection.txt").Contains("backedUp=True"))throw new Exception("Back up first");var main=Main();var forest=SceneManager.GetSceneByPath(Forest);if(!forest.IsValid()||!forest.isLoaded)throw new Exception("Forest must be loaded");if(main.GetRootGameObjects().Any(g=>g.name=="P2 - Forest Ruins Assets"))throw new Exception("Scenes already merged");var camera=View(main);Vector3 cameraPosition=camera.transform.position;Quaternion cameraRotation=camera.transform.rotation;float fov=camera.fieldOfView;var allObjects=main.GetRootGameObjects().Concat(forest.GetRootGameObjects()).SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var poses=allObjects.ToDictionary(t=>t.GetInstanceID(),t=>t.localToWorldMatrix);int renderersBefore=allObjects.Count(t=>t.GetComponent<Renderer>());var forestRoots=forest.GetRootGameObjects();var group=new GameObject("P2 - Forest Ruins Assets");SceneManager.MoveGameObjectToScene(group,main);
 foreach(var root in forestRoots){SceneManager.MoveGameObjectToScene(root,main);root.transform.SetParent(group.transform,true);}if(!EditorSceneManager.CloseScene(forest,true))throw new Exception("Could not close empty forest scene");SceneManager.SetActiveScene(main);int disabledLights=0,disabledCameras=0,disabledVolumes=0;foreach(var light in group.GetComponentsInChildren<Light>(true)){light.enabled=false;disabledLights++;}foreach(var c in group.GetComponentsInChildren<Camera>(true)){c.enabled=false;if(c.CompareTag("MainCamera"))c.tag="Untagged";disabledCameras++;}foreach(var listener in group.GetComponentsInChildren<AudioListener>(true))listener.enabled=false;foreach(var v in group.GetComponentsInChildren<Volume>(true)){v.enabled=false;disabledVolumes++;}
 var oldProfile=camera.GetComponent<MeadowCameraFocus>().focusProfile;string profilePath="Assets/ArtStyleTest/OutAssets/Profiles/Out_ForestTone_Focus.asset";Directory.CreateDirectory("Assets/ArtStyleTest/OutAssets/Profiles");AssetDatabase.Refresh();if(AssetDatabase.LoadAssetAtPath<VolumeProfile>(profilePath))throw new Exception("New profile exists; inspect before repeating");if(!AssetDatabase.CopyAsset(AssetDatabase.GetAssetPath(oldProfile),profilePath))throw new Exception("Profile copy failed");var profile=AssetDatabase.LoadAssetAtPath<VolumeProfile>(profilePath);var reference=AssetDatabase.LoadAssetAtPath<VolumeProfile>("Assets/ArtStyleTest/ForestRuinsDetailed/Forest Atmosphere.asset");foreach(var source in reference.components.Where(c=>!(c is DepthOfField))){var destination=profile.components.FirstOrDefault(c=>c.GetType()==source.GetType());if(destination)EditorUtility.CopySerialized(source,destination);else{destination=UnityEngine.Object.Instantiate(source);destination.name=source.name;AssetDatabase.AddObjectToAsset(destination,profile);profile.components.Add(destination);}EditorUtility.SetDirty(destination);}
 var house=main.GetRootGameObjects().First(g=>g.name=="house");var door=house.GetComponentsInChildren<Transform>(true).FirstOrDefault(t=>t.name=="Centre locking strip")??house.transform;var focus=camera.GetComponent<MeadowCameraFocus>();focus.focusProfile=profile;focus.focusTarget=door;focus.focusDistance=Mathf.Max(.5f,Vector3.Dot(door.position-cameraPosition,camera.transform.forward));focus.focalLength=85;focus.aperture=4;focus.depthOfField=true;focus.Apply();var cameraVolume=camera.GetComponent<Volume>();cameraVolume.sharedProfile=profile;var style=main.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeadowPainterlyStyle>(true)).First();style.grassColour=new Color(.45f,.51f,.31f,1);style.grassSunlitColour=new Color(.60f,.65f,.42f,1);style.grassShadeColour=new Color(.29f,.36f,.25f,1);style.grassShadowStrength=.70f;style.grassPatchVariation=.045f;style.Apply();
 int moved=0;foreach(var t in allObjects){var before=poses[t.GetInstanceID()];var after=t.localToWorldMatrix;float difference=0;for(int i=0;i<16;i++)difference=Mathf.Max(difference,Mathf.Abs(before[i]-after[i]));if(difference>.001f)throw new Exception("Geometry moved: "+t.name+" difference="+difference);moved++;}if(camera.transform.position!=cameraPosition||Quaternion.Angle(camera.transform.rotation,cameraRotation)>.001f||Mathf.Abs(camera.fieldOfView-fov)>.001f)throw new Exception("P1 camera framing changed");int rendererCount=main.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Count();if(rendererCount!=renderersBefore)throw new Exception("Renderer count changed");foreach(var c in profile.components)EditorUtility.SetDirty(c);foreach(var o in new UnityEngine.Object[]{focus,cameraVolume,style,profile})EditorUtility.SetDirty(o);AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(main);if(!EditorSceneManager.SaveScene(main))throw new Exception("Merged scene save failed");Selection.activeGameObject=camera.gameObject;SceneView.RepaintAll();Capture(camera,"Out_merged_forest_tone_preview.png");b.AppendLine("mergedScene="+Out+" importedRoots="+forestRoots.Length+" allRenderers="+rendererCount+" objectsWithPreservedWorldPose="+moved+" disabledDuplicateLights="+disabledLights+" disabledDuplicateCameras="+disabledCameras+" disabledDuplicateVolumes="+disabledVolumes+" originalForestAssetPreserved=True p1CameraFramingUnchanged=True\nfocusTarget="+door.name+" focusDistance="+focus.EffectiveFocusDistance+" focalLength="+focus.focalLength+" aperture="+focus.aperture+" gradingProfile="+profilePath+" grassPalette=mutedSageAndOlive saved=True");}catch(Exception e){b.AppendLine(e.ToString());Debug.LogException(e);}File.WriteAllText(W+"out_forest_merge_result.txt",b.ToString());}
 }
